<?php

declare(strict_types=1);

namespace Architex\Platform\OperatingSystem;

use Architex\Platform\Audit\AuditService;
use Architex\Platform\Project\ProjectContext;
use Architex\Platform\Project\ProjectPassportService;
use JsonException;
use PDO;

final readonly class ProductOperatingSystemService
{
    private const PRIORITY=['critical'=>0,'high'=>1,'medium'=>2,'low'=>3];
    private const HUMAN_GATES=['none','review','approval','signature','payment_release','municipal_submission','professional_certification','closeout_acceptance'];

    public function __construct(private PDO $pdo){}

    /** @return array<string,mixed> */
    public function projectSnapshot(string$o,string$u,string$role,string$projectId):array
    {
        $this->membership($o,$u,$role);$projectId=$this->id($projectId,'operating_project_not_found');
        $projects=new ProjectPassportService($this->pdo);$passport=$projects->find(new ProjectContext($o,$u,$projectId,$role));if($passport===null)throw new ProductOperatingSystemException('operating_project_not_found');
        $effectiveRole=$projects->effectiveRole($o,$u,$projectId);$records=$this->records($o,$projectId);$decisions=[];
        foreach($this->inboxRows($o,$u,$role,$projectId)as$row)$decisions[]=$this->decisionFromInbox($row,$effectiveRole,$passport->currentPhase->value);
        foreach($passport->missingRecords as$missing)$decisions[]=$this->missingRecordDecision($projectId,$effectiveRole,$passport->currentPhase->value,$missing);
        foreach($records as$record)if($record['status']==='pending_review')$decisions[]=$this->recordDecision($record,$effectiveRole,$passport->currentPhase->value);
        $decisions=$this->deduplicateAndSort($decisions);$risks=$this->risks($decisions);$score=$this->riskScore($risks);$cpd=$this->cpdSummary($o,$u,$effectiveRole);
        return[
            'context'=>['organisationId'=>$o,'projectId'=>$projectId,'projectName'=>$passport->projectName,'role'=>$effectiveRole,'roleLabel'=>$this->roleLabel($effectiveRole),'stage'=>$passport->currentPhase->value,'generatedAt'=>(new \DateTimeImmutable())->format(DATE_ATOM)],
            'records'=>$records,'decisions'=>$decisions,'inbox'=>array_values(array_filter($decisions,static fn($d)=>isset($d['inboxType']))),'risks'=>$risks,
            'operatingState'=>['status'=>count(array_filter($decisions,static fn($d)=>$d['priority']==='critical'))>0?'critical':($score>=35?'attention_required':($decisions===[]?'controlled':'awaiting_human')),'riskScore'=>$score,'decisionCount'=>count($decisions),'criticalDecisionCount'=>count(array_filter($decisions,static fn($d)=>$d['priority']==='critical')),'humanGatedDecisionCount'=>count(array_filter($decisions,static fn($d)=>$d['humanGate']!=='none')),'nextBestAction'=>$decisions[0]??null],
            'clientCommandCentre'=>array_map(static fn($d)=>['label'=>$d['title'],'plainEnglishValue'=>$d['plainLanguageSummary'],'nextStep'=>$d['actionTarget'],'priority'=>$d['priority'],'humanGate'=>$d['humanGate']],array_slice($decisions,0,6)),
            'cpd'=>$cpd,'guardrails'=>['aiAdvisoryOnly'=>true,'aiMayExecute'=>false,'movesMoney'=>false,'formalActionsRequireHumanConfirmation'=>true],
        ];
    }

    /** @return array<string,mixed> */
    public function mobileInbox(string$o,string$u,string$role):array
    {
        $this->membership($o,$u,$role);$projects=(new ProjectPassportService($this->pdo))->list($o,$u);$items=[];$projectSummaries=[];
        foreach($projects as$project){$snapshot=$this->projectSnapshot($o,$u,$role,$project->projectId);foreach($snapshot['inbox']as$item)$items[]=$item;foreach($snapshot['risks']as$risk)$items[]=$this->riskInboxItem($risk,$snapshot['context']);$projectSummaries[]=['projectId'=>$project->projectId,'projectName'=>$project->projectName,'stage'=>$project->currentPhase->value,'status'=>$snapshot['operatingState']['status'],'riskScore'=>$snapshot['operatingState']['riskScore'],'decisionCount'=>$snapshot['operatingState']['decisionCount']];}
        foreach($this->cpdSummary($o,$u,$role)['inboxItems']as$item)$items[]=$item;$items=$this->deduplicateAndSort($items);
        return['items'=>$items,'projects'=>$projectSummaries,'summary'=>['attentionCount'=>count($items),'criticalCount'=>count(array_filter($items,static fn($i)=>$i['priority']==='critical')),'humanConfirmationCount'=>count(array_filter($items,static fn($i)=>$i['humanGate']!=='none'))],'guardrails'=>['aiMayDraft'=>true,'aiMayExecute'=>false,'movesMoney'=>false]];
    }

    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function transitionInboxItem(string$o,string$u,string$role,string$id,string$status,array$input):array
    {
        $this->membership($o,$u,$role);$id=$this->id($id,'operating_inbox_item_not_found');if(!in_array($status,['read','resolved','dismissed'],true))throw new ProductOperatingSystemException('operating_inbox_status_invalid');
        $s=$this->pdo->prepare("SELECT *,LOWER(HEX(id)) id FROM inbox_items WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o) AND (assigned_user_id IS NULL OR assigned_user_id=UNHEX(:u) OR assigned_role=:role)");$s->execute(['id'=>$id,'o'=>$o,'u'=>$u,'role'=>$role]);$row=$s->fetch();if(!is_array($row))throw new ProductOperatingSystemException('operating_inbox_item_not_found');
        $payload=$this->decode($row['payload']);$gate=$this->humanGate($payload,$row['event_type']);$sensitive=$gate!=='none'&&in_array($status,['resolved','dismissed'],true);if($sensitive&&($input['humanConfirmed']??false)!==true)throw new ProductOperatingSystemException('operating_human_confirmation_required');$reason=$sensitive?$this->text($input['reason']??null,1000,'operating_transition_reason_required'):(is_string($input['reason']??null)?trim($input['reason']):null);
        $this->pdo->prepare('UPDATE inbox_items SET status=:status,resolved_at=CASE WHEN :terminal=1 THEN UTC_TIMESTAMP(6) ELSE NULL END WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o)')->execute(['status'=>$status,'terminal'=>in_array($status,['resolved','dismissed'],true)?1:0,'id'=>$id,'o'=>$o]);
        (new AuditService($this->pdo))->append($o,$u,'operating.inbox_transitioned','inbox_item',$id,['status'=>$status,'humanGate'=>$gate,'humanConfirmed'=>($input['humanConfirmed']??false)===true,'reason'=>$reason]);
        return['id'=>$id,'status'=>$status,'humanGate'=>$gate,'humanConfirmed'=>($input['humanConfirmed']??false)===true,'reason'=>$reason];
    }

    /** @return list<array<string,mixed>> */ private function records(string$o,string$p):array{$s=$this->pdo->prepare('SELECT LOWER(HEX(id)) id,module_key sourceModule,record_type recordType,title,status,payload,approvals,linked_record_ids linkedRecordIds,created_at createdAt FROM project_records WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) ORDER BY created_at DESC LIMIT 200');$s->execute(['o'=>$o,'p'=>$p]);$rows=$s->fetchAll();foreach($rows as&$r){$r['payload']=$this->decode($r['payload']);$r['approvals']=$this->decode($r['approvals']);$r['linkedRecordIds']=$this->decode($r['linkedRecordIds']);}unset($r);return$rows;}
    /** @return list<array<string,mixed>> */ private function inboxRows(string$o,string$u,string$role,string$p):array{$s=$this->pdo->prepare("SELECT *,LOWER(HEX(id)) id FROM inbox_items WHERE organisation_id=UNHEX(:o) AND project_id=UNHEX(:p) AND status IN ('open','read') AND (assigned_user_id IS NULL OR assigned_user_id=UNHEX(:u) OR assigned_role=:role) ORDER BY FIELD(priority,'critical','high','medium','low'),created_at DESC LIMIT 100");$s->execute(['o'=>$o,'p'=>$p,'u'=>$u,'role'=>$role]);return$s->fetchAll();}
    /** @param array<string,mixed> $row @return array<string,mixed> */ private function decisionFromInbox(array$row,string$role,string$stage):array{$payload=$this->decode($row['payload']);$source=$this->sourceModule($payload,$row['event_type']);$gate=$this->humanGate($payload,$row['event_type']);$status=$row['status']==='resolved'?'completed':($row['priority']==='critical'?'blocked':($gate==='none'?'advisory':'awaiting_human'));return['id'=>$row['id'],'title'=>$row['title'],'plainLanguageSummary'=>$row['detail'],'role'=>$row['assigned_role']?:$role,'stage'=>$stage,'sourceModule'=>$source,'priority'=>$row['priority'],'status'=>$status,'linkedRecordIds'=>$this->stringList($payload['linkedRecordIds']??[]),'humanGate'=>$gate,'aiMayDraft'=>true,'aiMayExecute'=>false,'actionTarget'=>is_string($payload['actionTarget']??null)?$payload['actionTarget']:$this->target($source),'inboxType'=>$this->inboxType($source,$gate),'mobileLabel'=>$row['title'],'mobileCta'=>$gate==='none'?'Review':'Review and confirm','createdAt'=>$row['created_at']];}
    /** @param array{recordType:string,priority:string,reason:string} $missing @return array<string,mixed> */ private function missingRecordDecision(string$p,string$role,string$stage,array$missing):array{$source=$this->sourceFromText($missing['recordType']);$title='Provide '.str_replace('_',' ',$missing['recordType']);return['id'=>'missing-'.$p.'-'.$missing['recordType'],'title'=>$title,'plainLanguageSummary'=>$missing['reason'],'role'=>$role,'stage'=>$stage,'sourceModule'=>$source,'priority'=>$missing['priority'],'status'=>'blocked','linkedRecordIds'=>[],'humanGate'=>'review','aiMayDraft'=>true,'aiMayExecute'=>false,'actionTarget'=>$this->target($source),'inboxType'=>'document_request','mobileLabel'=>$title,'mobileCta'=>'Open source'];}
    /** @param array<string,mixed> $record @return array<string,mixed> */ private function recordDecision(array$record,string$role,string$stage):array{$source=$this->sourceFromText($record['sourceModule']);$title='Review '.$record['title'];return['id'=>'record-'.$record['id'],'title'=>$title,'plainLanguageSummary'=>'This project record is awaiting accountable human review before it can be relied on.','role'=>$role,'stage'=>$stage,'sourceModule'=>$source,'priority'=>'medium','status'=>'awaiting_human','linkedRecordIds'=>array_values(array_unique([$record['id'],...$this->stringList($record['linkedRecordIds'])])),'humanGate'=>'review','aiMayDraft'=>true,'aiMayExecute'=>false,'actionTarget'=>$this->target($source),'inboxType'=>'approval_required','mobileLabel'=>$title,'mobileCta'=>'Open source'];}
    /** @param list<array<string,mixed>> $decisions @return list<array<string,mixed>> */ private function deduplicateAndSort(array$decisions):array{$seen=[];$out=[];foreach($decisions as$d){if(isset($seen[$d['id']]))continue;$seen[$d['id']]=true;$out[]=$d;}usort($out,fn($a,$b)=>(self::PRIORITY[$a['priority']]??9)<=>(self::PRIORITY[$b['priority']]??9));return$out;}
    /** @param list<array<string,mixed>> $decisions @return list<array<string,mixed>> */ private function risks(array$decisions):array{$risks=[];foreach($decisions as$d)if(in_array($d['priority'],['critical','high'],true)){$category=match($d['sourceModule']){'finance'=>'budget','municipal'=>'municipal','messaging'=>'communication','closeout'=>'closeout','cpd'=>'cpd','deployment'=>'deployment','api'=>'api','governance','documents'=>'compliance',default=>'delay'};$risks[]=['id'=>'risk-'.$d['id'],'sourceModule'=>$d['sourceModule'],'category'=>$category,'severity'=>$d['priority'],'title'=>$d['title'],'detail'=>$d['plainLanguageSummary'],'linkedRecordIds'=>$d['linkedRecordIds'],'recommendedIntervention'=>'Route to '.$d['role'].' in the Mobile Decision Centre and require '.($d['humanGate']==='none'?'review':str_replace('_',' ',$d['humanGate'])).'.','humanGate'=>$d['humanGate'],'advisoryOnly'=>true];}return$risks;}
    /** @param list<array<string,mixed>> $risks */ private function riskScore(array$risks):int{$weights=['critical'=>35,'high'=>20,'medium'=>8,'low'=>2];$score=0;foreach($risks as$r)$score+=$weights[$r['severity']]??0;return min(100,$score);}
    /** @param array<string,mixed> $risk @param array<string,mixed> $context @return array<string,mixed> */ private function riskInboxItem(array$risk,array$context):array{return['id'=>'inbox-'.$risk['id'],'title'=>$risk['title'],'plainLanguageSummary'=>$risk['detail'],'role'=>$context['role'],'stage'=>$context['stage'],'sourceModule'=>$risk['sourceModule'],'priority'=>$risk['severity'],'status'=>'advisory','linkedRecordIds'=>$risk['linkedRecordIds'],'humanGate'=>'review','aiMayDraft'=>true,'aiMayExecute'=>false,'actionTarget'=>$this->target($risk['sourceModule']),'inboxType'=>'risk_warning','mobileLabel'=>'Risk warning: '.$risk['title'],'mobileCta'=>'Open source'];}
    /** @return array<string,mixed> */ private function cpdSummary(string$o,string$u,string$role):array{$s=$this->pdo->prepare('SELECT professional_body,cycle_end,participation_role FROM cpd_professional_profiles WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u) AND status=\'active\'');$s->execute(['o'=>$o,'u'=>$u]);$profile=$s->fetch();if(!is_array($profile))return['professionalBody'=>'unknown','status'=>'not_configured','recordCount'=>0,'certificateReadyCount'=>0,'paymentRetryCount'=>0,'inboxItems'=>[],'governanceNotes'=>['CPD remains separate from Professional Toolboxes.','Professional-body rules are not generalised.']];$count=$this->pdo->prepare('SELECT COUNT(*) FROM cpd_professional_records WHERE organisation_id=UNHEX(:o) AND learner_user_id=UNHEX(:u)');$count->execute(['o'=>$o,'u'=>$u]);$records=(int)$count->fetchColumn();$ready=$this->pdo->prepare("SELECT COUNT(*) FROM cpd_attempts a LEFT JOIN cpd_certificates c ON c.attempt_id=a.id WHERE a.organisation_id=UNHEX(:o) AND a.learner_user_id=UNHEX(:u) AND a.status='passed' AND c.id IS NULL");$ready->execute(['o'=>$o,'u'=>$u]);$certificateReady=(int)$ready->fetchColumn();$retry=$this->pdo->prepare("SELECT COUNT(*) FROM cpd_payment_events WHERE organisation_id=UNHEX(:o) AND processing_status='failed'");$retry->execute(['o'=>$o]);$paymentRetries=(int)$retry->fetchColumn();$days=(int)(new \DateTimeImmutable())->diff(new \DateTimeImmutable($profile['cycle_end']))->format('%r%a');$items=[];if($days<=90){$priority=$days<0?'high':'medium';$items[]=$this->cpdItem('cpd-cycle-'.$u,$days<0?'CPD cycle record needs review':'CPD cycle ending soon',$days<0?'Your recorded CPD cycle has ended. Review body-specific evidence and manual submission requirements.':'Review body-specific CPD evidence before the cycle closes.',$role,$priority,'professional_certification');}if($certificateReady>0)$items[]=$this->cpdItem('cpd-certificate-'.$u,'CPD certificate ready for issue',$certificateReady.' passed assessment(s) need learner-controlled certificate issue before professional-record use.',$role,'medium','professional_certification');if($paymentRetries>0)$items[]=$this->cpdItem('cpd-payment-'.$o,'CPD payment support required',$paymentRetries.' provider event(s) failed and require manual support. No entitlement or money movement is inferred.',$role,'high','payment_release');return['professionalBody'=>$profile['professional_body'],'status'=>$items===[]?'on_track':'attention_required','recordCount'=>$records,'certificateReadyCount'=>$certificateReady,'paymentRetryCount'=>$paymentRetries,'inboxItems'=>$items,'governanceNotes'=>['CPD remains separate from Professional Toolboxes.','Do not apply SACAP credit logic generically across professional bodies.','Certificates support professional records but do not replace statutory review.']];}
    /** @return array<string,mixed> */ private function cpdItem(string$id,string$title,string$summary,string$role,string$priority,string$gate):array{return['id'=>$id,'title'=>$title,'plainLanguageSummary'=>$summary,'role'=>$role,'stage'=>'platform_wide','sourceModule'=>'cpd','priority'=>$priority,'status'=>'awaiting_human','linkedRecordIds'=>[],'humanGate'=>$gate,'aiMayDraft'=>true,'aiMayExecute'=>false,'actionTarget'=>'cpd','inboxType'=>'cpd_reminder','mobileLabel'=>$title,'mobileCta'=>'Review and confirm'];}
    /** @param array<string,mixed> $payload */ private function sourceModule(array$payload,string$event):string{$value=$payload['sourceModule']??null;return is_string($value)?$this->sourceFromText($value):$this->sourceFromText($event);}
    private function sourceFromText(string$text):string{$text=strtolower($text);return match(true){str_contains($text,'pay'),str_contains($text,'finance'),str_contains($text,'commercial')=>'finance',str_contains($text,'municipal'),str_contains($text,'planning')=>'municipal',str_contains($text,'message'),str_contains($text,'communication'),str_contains($text,'reply')=>'messaging',str_contains($text,'site'),str_contains($text,'snag'),str_contains($text,'ncr')=>'site',str_contains($text,'closeout'),str_contains($text,'handover')=>'closeout',str_contains($text,'cpd')=>'cpd',str_contains($text,'deploy'),str_contains($text,'release')=>'deployment',str_contains($text,'agent'),str_contains($text,'ai_')=>'agent',str_contains($text,'drawing'),str_contains($text,'document')=>'documents',str_contains($text,'approval'),str_contains($text,'trust')=>'governance',default=>'command_centre'};}
    /** @param array<string,mixed> $payload */ private function humanGate(array$payload,string$event):string{$value=$payload['humanGate']??null;if(is_string($value)&&in_array($value,self::HUMAN_GATES,true))return$value;$source=$this->sourceFromText($event);return match($source){'finance'=>'payment_release','municipal'=>'municipal_submission','closeout'=>'closeout_acceptance','cpd'=>'professional_certification','governance'=>'approval',default=>'review'};}
    private function inboxType(string$source,string$gate):string{return match($source){'messaging'=>'message_reply','municipal'=>'municipal_action','finance'=>'payment_review','site'=>'site_issue','closeout'=>'closeout_blocker','cpd'=>'cpd_reminder','deployment'=>'release_gate','agent'=>'agent_recommendation',default=>$gate==='none'?'document_request':'approval_required'};}
    private function target(string$source):string{return match($source){'finance'=>'payments_escrow','municipal'=>'municipal','messaging'=>'inbox','site'=>'site_diary','closeout'=>'closeout','cpd'=>'cpd','deployment'=>'release_gate','documents'=>'documents_drawings',default=>'project_passport'};}
    private function roleLabel(string$role):string{return match(strtolower($role)){'client'=>'Client / developer','developer'=>'Developer','architect'=>'Architect / lead professional','bep'=>'Built-environment professional','contractor'=>'Contractor','subcontractor'=>'Subcontractor','supplier'=>'Supplier','freelancer'=>'Freelancer / candidate','admin','owner'=>'Platform administrator',default=>ucwords(str_replace('_',' ',$role))};}
    private function membership(string$o,string$u,string$role):void{$s=$this->pdo->prepare("SELECT role FROM organisation_memberships WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u) AND status='active'");$s->execute(['o'=>$o,'u'=>$u]);if($s->fetchColumn()!==$role)throw new ProductOperatingSystemException('operating_membership_required');}
    private function id(mixed$v,string$error):string{if(!is_string($v)||preg_match('/\A[a-f0-9]{32}\z/i',$v)!==1)throw new ProductOperatingSystemException($error);return strtolower($v);}
    private function text(mixed$v,int$max,string$error):string{if(!is_string($v)||trim($v)===''||mb_strlen(trim($v))>$max)throw new ProductOperatingSystemException($error);return trim($v);}
    /** @return array<mixed> */ private function decode(mixed$v):array{if(!is_string($v))return[];try{$d=json_decode($v,true,512,JSON_THROW_ON_ERROR);}catch(JsonException){return[];}return is_array($d)?$d:[];}
    /** @return list<string> */ private function stringList(mixed$v):array{if(!is_array($v))return[];$out=[];foreach($v as$x)if(is_string($x)&&$x!=='')$out[]=$x;return array_values(array_unique($out));}
}
